import net from 'node:net';
import tls from 'node:tls';
import dns from 'node:dns';
import { writeFileSync } from 'node:fs';
const attempts = [];
function deny(kind, details = null) { attempts.push({ kind, details, stack: new Error().stack }); throw new Error('External network denied during offline regression'); }
net.Socket.prototype.connect = function () { return deny('socket'); };
tls.connect = () => deny('tls');
dns.lookup = () => deny('dns'); dns.promises.lookup = async () => deny('dns');
const originalFetch = globalThis.fetch;
globalThis.fetch = (input, ...args) => { const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
  if (url.startsWith('data:')) return originalFetch(input, ...args);
  return deny('fetch', url.split(':', 1)[0]); };
process.once('exit', () => writeFileSync(new URL(`./network-audit-${process.env.OFFLINE_AUDIT_RUN ?? 'initial'}-${process.pid}.json`, import.meta.url), JSON.stringify({ pid: process.pid, argv: process.argv, attempts })));

